pub const EXACT_RULES: &[(&str, &str)] = &[("acct01", "process accounting syscall support not configured"), ("acct02", "process accounting syscall support not configured"), ("arch_prctl01", "x86_64-specific arch_prctl testcase"), ("kill13", "requires CONFIG_UBSAN_SIGNED_OVERFLOW"), ("msgctl05", "requires msqid64_ds time_high ABI"), ("msgstress01", "long SysV message queue stress case"), ("signal06", "x86_64-only signal testcase"), ("sysinfo03", "requires time namespace kernel config"), ("timerfd04", "requires time namespace kernel config")];
pub fn skip(name: &str) -> Option<&'static str> { EXACT_RULES.iter().find(|(case, _)| *case == name).map(|(_, reason)| *reason) }
